```json
{"concepto": "Principal (主体)","enunciado": "可被认证和授权的实体，可以是人、service account、workload 或 agent","problema": "Definir qué entidades pueden ser autenticadas y autorizadas en un sistema","limite": "","patron": "Una entidad identificable que puede poseer permisos, realizar acciones y ser auditada","linea": 42}
{"concepto": "Identity Provider (身份提供者)","enunciado": "维护主体状态并向应用提供可信身份断言","problema": "Centralizar y hacer confiable la información de identidad para múltiples aplicaciones","limite": "","patron": "Una autoridad central mantiene datos de identidad y proporciona aserciones verificables que otras partes aceptan sin verificar directamente","linea": 42}
{"concepto": "Authentication (认证)","enunciado": "回答'你是谁'","problema": "Verificar que un principal es efectivamente quien afirma ser","limite": "","patron": "Proceso que convierte una afirmación de identidad en un hecho verificado","linea": 42}
{"concepto": "Authorization (授权)","enunciado": "回答'你能对哪个资源做什么'","problema": "Determinar qué acciones está permitido realizar un principal autenticado","limite": "","patron": "Decisión que mapea un principal verificado a acciones y recursos permitidos según políticas","linea": 42}
{"concepto": "Session/Token (会话/令牌)","enunciado": "把一次验证结果转成有限时间内可复用的访问能力","problema": "Evitar reverificar identidad en cada solicitud manteniendo un registro auditable","limite": "有限时间内（temporal, puede ser revocado)","patron": "Un artefacto temporal criptográficamente vinculado que representa autorización previamente verificada sin requerir re-autenticación","linea": 42}
{"concepto": "Single Sign-On (单点登录)","enunciado": "让用户通过一个受信任 IdP 访问多个应用，减少重复凭据并集中 policy","problema": "Reducir fricción de autenticación y centralizar políticas de acceso en múltiples aplicaciones","limite": "","patron": "Un IdP confiable proporciona identidad a múltiples aplicaciones independientes; los usuarios se autentican una vez","linea": 59}
{"concepto": "Multi-Factor Authentication (多因素认证)","enunciado": "要求来自不同 factor category 的证据，例如 possession 与 inherence","problema": "Aumentar la seguridad contra el compromiso de un único factor de autenticación","limite": "","patron": "Requerir evidencia de múltiples categorías independientes (conocimiento, posesión, inherencia, localización) para aumentar la certeza de identidad","linea": 97}
{"concepto": "WebAuthn/Passkey (网络认证/通行密钥)","enunciado": "使用公钥凭据，可提供 phishing-resistant authentication","problema": "Proporcionar autenticación resistente al phishing sin usar contraseñas compartidas","limite": "","patron": "El servidor desafía al dispositivo del usuario con un problema criptográfico; solo el dispositivo correcto puede responder sin revelar un secreto maestro","linea": 97}
{"concepto": "Service-Level Objective (服务水平目标)","enunciado": "是系统在统计窗口内承诺达到的可测目标，例如成功认证比例或 p99 latency","problema": "Establecer compromisos medibles sobre la calidad del servicio para alinear proveedores y clientes","limite": "","patron": "Un número o métrica que cuantifica desempeño esperado en un período; los fallos se contabilizan contra este objetivo","linea": 119}
{"concepto": "Blast Radius (故障半径)","enunciado": "表示一次错误影响的 tenant、region、application 或 principal 范围","problema": "Cuantificar el alcance potencial de una falla para limitar daño en sistemas multi-tenant","limite": "","patron": "El número de entidades independientes (arrendatarios, regiones, aplicaciones) afectadas por una única falla; mitiga con aislamiento","linea": 119}
{"concepto": "Availability Formula (可用性公式)","enunciado": "\\[\\mathrm{availability}=1-\\frac{N_{failed}}{N_{eligible}}.\\]","problema": "Medir objetivamente el porcentaje de solicitudes exitosas para establecer SLOs","limite": "No debe promediar errores de seguridad/correctitud; requiere métricas separadas para false allow, false deny, revoke delay","patron": "La proporción de solicitudes completadas exitosamente sobre el total elegible; debe separar fallos de disponibilidad de fallos de seguridad","linea": 130}
{"concepto": "Assurance (保障等级)","enunciado": "描述系统对'当前主体确实是账户拥有者'的置信程度，取决于 authenticator、设备和上下文","problema": "Adaptar el nivel de verificación de identidad según el riesgo de la operación solicitada","limite": "","patron": "Un nivel de confianza variable: operaciones de bajo riesgo reutilizan sesiones antiguas, operaciones sensibles requieren re-autenticación","linea": 137}
{"concepto": "Incident Response Lifecycle (事件响应生命周期)","enunciado": "包含 detection、containment、investigation、remediation 和 notification 五个阶段","problema": "Establecer un proceso estructurado que cierre el aprendizaje después de cada incidente de seguridad","limite": "","patron": "Cinco fases secuenciales: identificar el incidente, detener el daño actual, entender qué sucedió, cambiar el sistema, informar a clientes","linea": 197}
{"concepto": "Containment vs Remediation (包含 vs 补救)","enunciado": "禁用 service account、revoke session 是 containment（停止当前伤害），修复 credential、增强 telemetry 是 remediation（降低复发概率）","problema": "Diferenciar acciones que detienen daño inmediato de cambios que previenen recurrencia","limite": "","patron": "Dos categorías temporales: temporal (horas) detiene el daño actual con riesgo de reversión; permanente (días-semanas) mejora defensas de forma duradera","linea": 207}
{"concepto": "Zero Trust Architecture (零信任架构)","enunciado": "不因网络位置或一次登录永久授予信任。每次访问按 subject、asset、environment 与 policy 做显式决策，采用 least privilege，并假设网络可能已被攻破","problema": "Eliminar la suposición de que ubicación de red o autenticación previa son suficientes; adaptar confianza según contexto","limite": "前提是清洁 identity lifecycle、清晰 ownership 与可撤销 entitlements","patron": "Cada solicitud se evalúa independientemente: identidad verificada + contexto + política = decisión; sin asumir confianza previa del dispositivo o red","linea": 245}
{"concepto": "Service Account (服务账户)","enunciado": "供软件或 workload 使用的非人类账户","problema": "Permitir que software y procesos automáticos actúen con identidad verificable","limite": "","patron": "Una identidad no humana ligada a un software o proceso específico que puede ser auditado y revocado independientemente","linea": 269}
{"concepto": "Non-Human Identity (非人类身份)","enunciado": "泛指 service、workload、device 或 agent principal","problema": "Clasificar y gobernar identidades que no son humanas pero requieren autenticación y delegación de autoridad","limite": "","patron": "Cualquier entidad no humana que ejecuta acciones; requiere principal, delegación explícita, auditoría y revocabilidad","linea": 269}
{"concepto": "OAuth 2.0","enunciado": "是 delegated authorization framework，让 client 获得 scoped access token，而不必持有用户密码","problema": "Permitir acceso delegado sin revelar credenciales principales de largo plazo","limite": "","patron": "Un servidor central emite tokens limitados en alcance y tiempo en lugar de compartir la contraseña del usuario","linea": 269}
{"concepto": "OpenID Connect (OpenID Connect)","enunciado": "在 OAuth 之上提供身份层，用 ID token 表达认证结果","problema": "Proporcionar tanto autenticación como autorización delegada en un marco unificado","limite": "","patron": "Capa de identidad que proporciona aserciones verificables de quién es el usuario, construida sobre la delegación de autorización de OAuth","linea": 269}
{"concepto": "Access Token (访问令牌)","enunciado": "是向 resource server 表达授权的凭证；bearer token 被谁拿到谁就能使用，因此必须限制 scope、audience 和 lifetime，并尽量采用 sender-constrained/bound token","problema": "Proporcionar evidencia criptográfica de autorización limitada a recursos y tiempos específicos","limite": "bearer token 如果被盗可被任何人使用；必须伴随 scope、audience、lifetime 限制","patron": "Un artefacto temporal que contiene afirmación de autorización; cualquiera que lo posea puede usarlo, por eso debe ser limitado y efímero","linea": 281}
{"concepto": "Token Exchange (令牌交换)","enunciado": "允许系统把已有 token 交换为面向特定 audience、权限更窄的新 token，同时保留 actor 与 subject 关系","problema": "Permitir que un agente obtenga permisos limitados sin acceso a tokens amplios del usuario","limite": "","patron": "Transformar un token amplio en tokens estrechos para audiencias específicas mientras se mantiene la cadena de auditoría de quién autorizó qué","linea": 274}
{"concepto": "Delegation Record (委派记录)","enunciado": "每次 agent delegation 至少记录：human/organizational owner、agent principal、subject、requested task、resource audience、approved scopes、policy/version、issue/expiry、token/session ID、tool actions、result、revocation reason","problema": "Permitir auditoría completa de quién autorizó qué agente para hacer qué acción","limite": "","patron": "Registro estructurado que vincula: autoridad delegante → agente → acción → auditoría; permite rastrear incidentes y responsabilidad","linea": 289}
{"concepto": "Trust Flywheel (信任飞轮)","enunciado": "可靠服务 → 客户扩大 deployment → 更丰富的 integration/context → security evidence → 客户信任 → 续约、reference、更深采用","problema": "Generar un ciclo de retroalimentación positiva donde confiabilidad atrae usuarios, que generan datos, que mejoran el servicio","limite": "飞轮可能反向运行：poorly handled incident 削弱 trust 并导致客户减少 deployment","patron": "Ciclo de refuerzo mutuo: confiabilidad atrae clientes → clientes usan más → datos ricos → mejores alertas y políticas → mayor confiabilidad","linea": 329}
{"concepto": "Wedge Strategy (楔形策略)","enunciado": "一个基础设施创业入口同时需要：today value（客户今天就愿意付费），tomorrow depth（入口能够扩展到完整平台）","problema": "Equilibrar el valor inmediato que justifica el pago con el potencial de crecimiento a largo plazo","limite": "两者缺一，产品要么没有现金流，要么没有长期平台空间","patron": "Comenzar con un problema urgente resoluble en semanas, que sea un punto de entrada natural a una plataforma más amplia","linea": 73}
{"concepto": "Identity Control Plane (身份控制平面)","enunciado": "把分散的 HR、directory、customer signup、partner federation 和 service identity 汇聚为统一 principal model，再对每次访问执行 authentication、authorization、session 与 lifecycle policy","problema": "Centralizar la toma de decisiones de identidad en un sistema coherente","limite": "不是所有数据的唯一 truth，但必须知道哪些 source 对哪些 attribute 拥有权威","patron": "Un sistema central que unifica múltiples fuentes heterogéneas de identidad y aplica políticas de forma consistente a todas las solicitudes","linea": 81}
{"concepto": "Directory (目录)","enunciado": "保存 principal profile、group、relationship、credential enrollment 和 lifecycle state；把异构 identity 映射成可预测的数据模型","problema": "Proporcionar una vista normalizada de identidades heterogéneas de múltiples fuentes","limite": "","patron": "Base de datos centralizada que normaliza identidades de múltiples fuentes (HR, LDAP, aplicaciones) en un esquema uniforme","linea": 85}
{"concepto": "Source of Truth (权威来源)","enunciado": "应按字段定义：例如 HR 决定 employment status，应用决定本地 role，IdP 决定 authenticator enrollment，不能用'最后写入者'覆盖所有语义","problema": "Resolver conflictos cuando múltiples sistemas pueden escribir el mismo atributo","limite": "","patron": "Cada atributo tiene un propietario autorizado según política; los conflictos se resuelven por regla explícita, no por orden temporal","linea": 87}
{"concepto": "Provisioning (供应)","enunciado": "把账户和 entitlement 创建到下游应用","problema": "Automatizar la creación y actualización de acceso en sistemas múltiples","limite": "离职事件多久传播、derived group 如何重算","patron": "Propagación automática de cambios de identidad desde un sistema central a múltiples aplicaciones; permite sincronización de ciclo de vida","linea": 102}
{"concepto": "SCIM (System for Cross-domain Identity Management)","enunciado": "用标准 API 同步用户与 group","problema": "Estandarizar y automatizar la sincronización de identidades entre sistemas","limite": "","patron": "Un protocolo estándar REST que permite que un sistema central propague cambios de identidad a otros sistemas mediante APIs uniformes","linea": 102}
{"concepto": "Policy-Based Access Decision (基于策略的访问决策)","enunciado": "Request 带 principal、device/network 和 target app；context 汇集 profile、group、risk 与 session history；policy 输出 allow、deny 或 step-up；outcome 创建 session/token 并记录 audit event","problema": "Tomar decisiones de acceso complejas basadas en múltiples señales de contexto","limite": "为了调查一次异常 allow，系统必须保存 policy/version、关键 attribute、risk signal、authenticator、decision reason","patron": "Cada decisión combina identidad verificada, contexto de dispositivo/red, historial de sesión y políticas; la decisión es auditable e replicable","linea": 141}
```
